import re
import json

def recover_relations(response: str, atoms: dict[str, str]):
    relations = []

    # Cause-Effect
    cause_effect_pairs = re.findall(r"(.*) (caused|led to|resulted in|because) (.*)", response)
    for pair in cause_effect_pairs:
        source = None
        target = None
        for key, value in atoms.items():
            if pair[0] in value:
                source = int(key)
            if pair[2] in value:
                target = int(key)
        if source and target:
            relations.append({
                "source": source,
                "target": target,
                "sense": "Cause-Effect",
                "coupling": "entailment",
                "strength_band": "strong"
            })

    # Evidence
