                "source": source,
                "target": target,
                "sense": "Concession",
                "coupling": "none",
                "strength_band": "moderate"
            })

    # Alternative
    alternative_pairs = re.findall(r"(.*) (either|or) (.*)", response)
    for pair in alternative_pairs:
        source = None
        target = None
        for key, value in atoms.items():
            if pair[0] in value:
